-- nutzungsart
update public.fields set verification_status='verified_against_standard', verification_quote='Diese Norm gilt für Anlagen zur Nutzung von Regenwasser in Haushalten, Gewerbe- und Industriebetrieben sowie in öffentlichen Einrichtungen, in denen es $\mathbf{z . B}$ für Toilettenspülung, Kühlzwecke, Wasch- und Reinigungsanlagen und zur Bewässerung von Grünanlagen genutzt wird. | Nach der Trinkwasserverordnung ist für die Reinigung von Gegenständen, die bestimmungsgemäß nicht nur vorübergehend mit dem menschlichen Körper in Kontakt kommen (z.B. Wäschewaschen) Trinkwasser zur Verfügung zu stellen ${ }^{1)}$. — printed p.4', verification_note='md-verified 2026-09-05 (§1, printed p.4 derived); the §1 use list is exemplary ("z. B."), so the token "sonstige" is the EKOWAI catch-all; Wäschewaschen is excluded by the TrinkwV sentence [VC]', verified_at=now() where id='b565e781-8810-468d-ae6f-4a48dca31546' and verification_status not in ('verified_against_standard','corrected');

-- anwendungsbereich
update public.fields set verification_status='verified_against_standard', verification_quote='Diese Norm gilt für Anlagen zur Nutzung von Regenwasser in Haushalten, Gewerbe- und Industriebetrieben sowie in öffentlichen Einrichtungen, in denen es $\mathbf{z . B}$ für Toilettenspülung, Kühlzwecke, Wasch- und Reinigungsanlagen und zur Bewässerung von Grünanlagen genutzt wird. | Wird die ständige Betriebssicherheit der Anlage gefordert, z. B. in öffentlichen Einrichtungen, muss die Regenwassernutzungsanlage mit einem Vorlagebehälter mit freiem Auslauf (Nachspeisemodul oder Hybridanlage) so konzipiert sein, dass sie auch unabhängig vom Regenwasserspeicher betrieben werden kann. — printed p.4, p.17', verification_note='md-verified 2026-09-05 (§1 + §9, printed p.4, p.17 derived); enum = the three application areas named in §1 [VC]', verified_at=now() where id='4d558b72-9741-41ea-953c-ff355d3b584f' and verification_status not in ('verified_against_standard','corrected');

