-- dachwerkstoff_bewertet
update public.fields set verification_status='verified_against_standard', verification_quote='Folgende Dachwerkstoffe bzw. -systeme sind in Abhängigkeit von den Anwendungsbereichen des Betriebswassers im Einzelfall zu bewerten: - Bei Gründächern tritt in der Regel langfristig eine bräunliche Färbung des Wassers ein. - Bei Bitumendächern tritt in vielen Fällen eine Gelbfärbung des Regenwassers ein. - Dächer aus asbesthaltigen Faserzement-Werkstoffen emittieren langfristig Fasern. - Bei neu erstellten großflächigen unbeschichteten Kupfer- und Zinkdächern können stark erhöhte Metallkonzentrationen im Dachablaufwasser auftreten. - Auf verwitterten rauen Dachflächen sammeln sich während Trockenzeiten Feststoffe an, die bei Regenfällen abgespült werden. — printed p.10', verification_note='md-verified 2026-09-05 (§5.2, printed p.10 derived); "sind [...] im Einzelfall zu bewerten" is an obligation although the field is not required — see STAGED S-10 [VC]', verified_at=now() where id='2dd3064d-693e-4e34-a380-60d7c82a8123' and verification_status not in ('verified_against_standard','corrected');

