update public.fields set verification_status='verified_against_standard', verification_quote='Filter sind grundsätzlich im Speicherzulauf einzubauen. | - Filter sind nach ihrer Reinigungsleistung (z. B. Wirkungsgrad, Standzeit, Durchlassweite) auszuwählen. Es sind genormte Filter zu verwenden ${ }^{4)}$. - Größe und hydraulische Leistungsfähigkeit des Filters sind für den Einbauort auszuwählen. Die Filter dürfen keine oder nur geringe Wasserverluste im Speicherzulauf verursachen. Es sind Filter zu verwenden, deren hydraulische Leistungsfähigkeit ${ }^{4)}$ geprüft wurde. | 4) Eine Norm für Anforderungen und Prüfung von Filtern (DIN 1989-2) befindet sich in Vorbereitung. — printed p.11', verification_note='md-verified 2026-09-05 (§6.2 + footnote 4, printed p.11 derived); "genormt" refers to DIN 1989-2, which in the 2002 edition was still in preparation (footnote 4) — gate CR-03 quotes the descriptive paragraph, not this bullet (STAGED S-3) [VC]', verified_at=now() where id='43922ca0-13fa-40bd-9e67-7679b59141ea' and verification_status not in ('verified_against_standard','corrected');

-- sedimentation_beruhigter_zulauf
update public.fields set verification_status='verified_against_standard', verification_quote='In Regenwasserspeichern ist zur Entfernung dieser Feststoffe eine Sedimentation zu ermöglichen. | - Der Zulauf sollte die Sedimentation durch Störströmungen - soweit möglich - nicht behindern und vorhandenes Sediment im Bereich der Speichersohle nicht wieder verteilen. Hierzu ist das Zulaufwasser z.B. diffus breitflächig auf dem Wasserspiegel zu verteilen oder über ein Zulaufrohr bis zum Speicherboden zu führen und dort in eine Aufwärtsströmung mit niedrigerer Austrittsgeschwindigkeit umzulenken (beruhigter Zulauf). — printed p.12', verification_note='md-verified 2026-09-05 (§6.3, printed p.12 derived); enabling sedimentation is "ist [...] zu ermöglichen" (hard), the Zulauf design itself is "sollte" (soft) — required-flag kept, noted in STAGED S-10 [VC]', verified_at=now() where id='e10c4313-e62a-4946-85e1-6c408b1ce4b1' and verification_status not in ('verified_against_standard','corrected');

