update public.fields set verification_status='verified_against_standard', verification_quote='Nachspeisung Vorrichtung für die zusätzliche Zuführung von Trink- oder Nichttrinkwasser in Betriebswasseranlagen | Die Qualität des nachgespeisten Wassers muss für den Verwendungszweck geeignet sein. — printed p.6–8, p.16', verification_note='md-verified 2026-09-05 (§3.28 + §9, printed p.6–8, p.16 derived); enum = the two media named in the §3.28 definition — clause retag to "§3.28; §9" proposed in STAGED S-4 [VC]', verified_at=now() where id='a71b07d1-6712-4528-be6e-985deaac91ee' and verification_status not in ('verified_against_standard','corrected');

-- sicherungseinrichtung_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Wenn Trinkwasser verwendet wird, muss die Nachspeisung über eine Sicherungseinrichtung Typ AA (ungehinderter freier Auslauf) oder Typ AB (freier Auslauf mit nicht kreisförmigem Überlauf) nach DIN EN 1717 erfolgen. Die Nachspeiseleitung ist nach DIN 1988-2 zu installieren und nach DIN 1988-3 zu bemessen. Die Möglichkeit der Überflutung der Sicherungseinrichtung (z. B. bei Rückstau) muss ausgeschlossen werden. Die Sicherungseinrichtung ist außerhalb des Regenwasserspeichers und außerhalb des Einstiegschachtes (Dom) zu installieren. — printed p.16–17', verification_note='md-verified 2026-09-05 (§9, printed p.16–17 derived); applies ONLY when Trinkwasser is the top-up medium — is_required=true is over-strict for Nichttrinkwasser systems (gate CR-06 already conditions correctly) — STAGED S-10 [VC]', verified_at=now() where id='46cd9779-30c8-42ee-a60f-771aad0c0a85' and verification_status not in ('verified_against_standard','corrected');

-- nachspeisung_volumenstrom
update public.fields set verification_status='verified_against_standard', verification_quote='Die Nachspeisung ist so auszulegen, dass an allen Entnahmestellen, die an die Regenwassernutzungsanlage angeschlossen sind, die einwandfreie Funktion ununterbrochen sichergestellt ist. Der maximale Volumenstrom der Wassernachspeisung muss mindestens dem Spitzendurchfluss nach DIN 1988-3 entsprechen. Wenn der minimale Füllstand des Speichers erreicht ist, muss sich die Nachspeisung automatisch einschalten. — printed p.16', verification_note='md-verified 2026-09-05 (§9, printed p.16 derived); PARTIAL — the floor (Spitzendurchfluss) comes from DIN 1988-3 (NR) and no comparator field exists, so the "mindestens" rule is not gate-able today (STAGED S-11) [VC]', verified_at=now() where id='9393add3-cf2d-4f88-bf06-dc377ab6d7bb' and verification_status not in ('verified_against_standard','corrected');

-- systemsteuerung_vorhanden
update public.fields set verification_status='verified_against_standard', verification_quote='Die Systemsteuerung steuert automatisch die Funktion der Regenwassernutzungsanlage und stellt somit die Versorgungssicherheit her. Zur Steuerung und Überwachung sind genormte Geräte zu verwenden. — printed p.17', verification_note='md-verified 2026-09-05 (§10, printed p.17 derived); no gate anchors this field (STAGED S-11d) [VC]', verified_at=now() where id='c48b0cf7-188b-4960-a8c0-a0eceee268d1' and verification_status not in ('verified_against_standard','corrected');

-- steuerung_funktionen
update public.fields set verification_status='verified_against_standard', verification_quote='Systemsteuerungen können folgende Funktionen beinhalten: - Steuerung der Nachspeisung - Füllstandsmessung - Rückstauüberwachung - Störmeldung - Pumpensteuerung - Verbrauchsmessung - Datenerfassung - Gebäudeleittechnik | Die jeweiligen Betriebszustände sollten an der Steuerung angezeigt werden. — printed p.17', verification_note='md-verified 2026-09-05 (§10, printed p.17 derived); the eight enum tokens are exactly the printed list ("können" = optional); the VDI 3814 reference in the description is NOT in the md; a single-select for concurrent functions is structurally a multi-select (STAGED S-12) [VC]', verified_at=now() where id='449e896d-014c-41a7-ac0c-aaf81c5e9d06' and verification_status not in ('verified_against_standard','corrected');

-- fuellstandueberwachung
update public.fields set verification_status='verified_against_standard', verification_quote='Der Füllstand des Regenwasserspeichers muss überwacht werden und sollte anzeigbar sein. Beim Erreichen des Mindestwasservolumens im Regenwasserspeicher ist die Nachspeisung so zu steuern, dass möglichst wenig Wasser nachgespeist wird. Funktionsstörungen sind durch Störmeldungen anzuzeigen. — printed p.17', verification_note='md-verified 2026-09-05 (§10, printed p.17 derived); monitoring is "muss", display is "sollte" [VC]', verified_at=now() where id='d6e5de2e-eb79-4fb7-bb7c-5b0eb9dde5bb' and verification_status not in ('verified_against_standard','corrected');

-- hybridbehaelter_volumen
update public.fields set verification_status='verified_against_standard', verification_quote='Hybridbehälter sind in Bezug auf die Betriebswasserpumpe als Vorlagebehälter zu betrachten und entsprechend zu dimensionieren. Ihr Volumen sollte nicht größer als der halbe Tagesbedarf an Betriebswasser sein. An der tiefsten Stelle des Hybridbehälters ist eine Ablassmöglichkeit vorzusehen. Bei Wassermangel erfolgt die Nachspeisung automatisch in den Hybridbehälter. — printed p.18', verification_note='md-verified 2026-09-05 (§11, printed p.18 derived); the ≤ half-daily-demand cap is "sollte" (soft) — warn-gate candidate against P_d × n in STAGED S-11g [VC]', verified_at=now() where id='aca75856-ea7c-4908-adb0-f1c75b7eadf9' and verification_status not in ('verified_against_standard','corrected');

-- leitungskennzeichnung
update public.fields set verification_status='verified_against_standard', verification_quote='Betriebswasserleitungen sind nach der Trinkwasserverordnung und nach DIN 2403 eindeutig und dauerhaft zu kennzeichnen. | Ergänzend sind Betriebswasserleitungen mit der Aufschrift „Betriebswasser“ oder „Regenwasser“ oder „Kein Trinkwasser“ zu kennzeichnen. | In der Nähe der Trinkwasserhauseinführung oder am Hauswasserzähler ist ein Hinweisschild mit sinngemäß folgender Aufschrift zu installieren: | Achtung! | In diesem Gebäude ist eine Regenwassernutzungsanlage installiert. Querverbindungen sind nicht zulässig. | An den Entnahmestellen ist ein bildliches Symbol nach DIN 4844-1 bzw. DIN 4844-2 oder ein Hinweisschild „Kein Trinkwasser“ sichtbar und dauerhaft anzubringen. — printed p.19', verification_note='md-verified 2026-09-05 (§12.7, printed p.19 derived) [VC]', verified_at=now() where id='aec5a393-6683-4171-8bc6-638352c0de3f' and verification_status not in ('verified_against_standard','corrected');

-- wasserzaehler_eingebaut
update public.fields set verification_status='verified_against_standard', verification_quote='Falls nach den örtlichen Gegebenheiten für die Ableitung des Abwassers aus der Regenwassernutzungsanlage eine Abwassergebühr zu zahlen ist und als Berechnungsgrundlage die genutzte Regenwassermenge herangezogen wird, ist der Einbau von Wasserzählern erforderlich. Wasserzähler müssen der DIN V $3260-10$ und den eichrechtlichen Vorschriften entsprechen. Der nachträgliche Einbau von Wasserzählern ist vorzusehen. | Unabhängig von gebührenrechtlichen Regelungen können Wasserzähler zur Kontrolle der Regenwassernutzungsanlage eingesetzt werden. — printed p.19', verification_note='md-verified 2026-09-05 (§12.9, printed p.19 derived); conditional obligation (fee based on used rainwater volume) [VC]', verified_at=now() where id='e7f2ad48-8a3f-4048-8b82-9b4d55f3d39a' and verification_status not in ('verified_against_standard','corrected');

-- ---------- DIN-1989-1-04 Auslegung der Speichergröße (Bemessung Nutzvolumen) ----------

-- n
update public.fields set verification_status='verified_against_standard', verification_quote='Der Betriebswasserbedarf im Haushalt setzt sich zusammen aus personenbezogenen Angaben (z. B. Toilette) nach $B W_{\mathrm{a}}=P_{\mathrm{d}} \times n \times 365$ | Dabei ist $B W_{\mathrm{a}} \quad$ Betriebswasserjahresbedarf $P_{\mathrm{d}} \quad$ personenbezogener Tagesbedarf n Anzahl der Personen — printed p.28', verification_note='md-verified 2026-09-05 (§16.3.7 Gl.(2) symbol list, printed p.28 derived) [VC]', verified_at=now() where id='ea87323d-cf31-47eb-8d61-026317fe4989' and verification_status not in ('verified_against_standard','corrected');

-- h_N
update public.fields set verification_status='verified_against_standard', verification_quote='Für eine genaue Auslegung sind die jeweils örtlich gültigen Niederschlagshöhen bei der örtlichen Behörde, beim Deutschen Wetterdienst, Offenbach am Main und bei der Zentralstelle für hydrometeorologische Entwicklungen und Anwendungen, Berlin erhältlich. Die Niederschlagshöhen betragen zwischen 500 mm und $1600 \mathrm{~mm} \mathrm{bzw} .500 \mathrm{l} / \mathrm{m}^{2}$ und $1600 \mathrm{l} / \mathrm{m}^{2}$ je Jahr. | $h_{\mathrm{N}} \quad$ die Niederschlagshöhe in Liter je Quadratmeter $\left(\mathrm{l} / \mathrm{m}^{2}\right)$ oder Millimeter $(\mathrm{mm})$ — printed p.26, p.27', verification_note='md-verified 2026-09-05 (§16.3.2 + §16.3.6 symbol list, printed p.26, p.27 derived); the 500–1600 span is descriptive of Germany, not a limit — warn-gate candidate in STAGED S-11e; value source = DWD / local authority (engineer_input) [VC]', verified_at=now() where id='15d1195b-ac1d-418a-9dc0-400ac4a08bf7' and verification_status not in ('verified_against_standard','corrected');

-- A_A
update public.fields set verification_status='verified_against_standard', verification_quote='Die Größe der Dachauffangfläche ist die berechnete Grundfläche des Hauses (zzgl. Dachüberstand) unabhängig von Dachform und Dachneigung. Wird nur eine Dachseite des Hauses als Auffangfläche genutzt, so wird auch nur die entsprechende Grundfläche berücksichtigt. Bei sonstigen Flächen wird die beregnete Grundfläche in Ansatz gebracht. | $A_{\mathrm{A}} \quad$ die Auffangfläche in Quadratmeter ( $\mathrm{m}^{2}$ ) — printed p.27', verification_note='md-verified 2026-09-05 (§16.3.3 + §16.3.6 symbol list, printed p.27 derived) [VC]', verified_at=now() where id='e912a324-e247-4d88-b264-53330e926021' and verification_status not in ('verified_against_standard','corrected');

-- e
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Ermittlung des Ertragsbeiwertes sind Lage, Neigung, Ausrichtung und Beschaffenheit der Auffangfläche zu Berücksichtigen. Als Planungsgrundlage für Neigung und Beschaffenheit der Auffangfläche können die Werte nach Tabelle 3 verwendet werden. | Tabelle 3 - Ertragsbeiwerte | Beschaffenheit & Ertragsbeiwert \% e | geneigtes Hartdach [...] & 0,8 | Flachdach unbekiest & 0,8 | Flachdach bekiest & 0,6 | Gründach intensiv & 0,3 | Gründach extensiv & 0,5 | Pflasterfläche/Verbundpflasterfläche & 0,5 | Asphaltbelag & 0,8 | a Abweichungen je nach Saugfähigkeit und Rauheit — printed p.27', verification_note='md-verified 2026-09-05 (§16.3.4 Tab. 3, printed p.27 derived); Tab. 3 is a planning basis ("können [...] verwendet werden", footnote a allows deviation) → e is an engineer choice with printed defaults keyed by auffangflaechen_art — lookup default + 0,3–0,8 warn gate proposed in STAGED S-11f/S-12; the md column head says "%" while the values are fractions (0,8) — Gl.(1) uses the fraction [VC]', verified_at=now() where id='61c80f4b-5aa3-4d3c-b777-fee201a8504e' and verification_status not in ('verified_against_standard','corrected');

-- eta
update public.fields set verification_status='verified_against_standard', verification_quote='Für hydraulisch wirkende Filtersysteme, die in die Speicherzuleitung eingesetzt werden, sind die Herstellerangaben bezüglich des nutzbaren Regenwasservolumenstromes zu berücksichtigen. | ANMERKUNG Bei regelmäßig gewarteten Filtersystemen wird in der Regel ein hydraulischer Filterwirkungsgrad von 0,9 erzielt. | hydraulischer Filterwirkungsgrad Verhältnis zwischen der dem Filter zulaufenden Wassermenge und der einer Nutzung zugeführten Wassermenge — printed p.27, p.6–8', verification_note='md-verified 2026-09-05 (§16.3.5 + §3.15, printed p.27, p.6–8 derived); 0,9 is an ANMERKUNG default ("in der Regel"), manufacturer data governs [VC]', verified_at=now() where id='34e35eec-ed92-4ba9-8795-deda6f6c624e' and verification_status not in ('verified_against_standard','corrected');

-- E_R
update public.fields set verification_status='verified_against_standard', verification_quote='Die jährliche theoretisch speicherbare Regenwassermenge ist nach Gleichung (1) zu berechnen: | E_{\mathrm{R}}=A_{\mathrm{A}} \times e \times h_{\mathrm{N}} \times \eta \tag{1} | Dabei ist $E_{\mathrm{R}} \quad$ der Regenwasserertrag in Liter je Jahr (I/a) — printed p.27', verification_note='md-verified 2026-09-05 (§16.3.6 Gl.(1), printed p.27 derived); "(I/a)" is the md OCR of "(l/a)"; derived field — engine output of equation 1 [VC]', verified_at=now() where id='35388ddc-8a75-40b5-a192-e24d0f4368e5' and verification_status not in ('verified_against_standard','corrected');

-- P_d
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 4 - Ermittlung des jährlichen Betriebswasserbedarfs | Verbraucher & personenbezogener Tagesbedarf & spezifischer Jahresbedarf | - Toiletten im Haushalt [...] & $24 \mathrm{l} /$ Person $\times$ Tag & - | - Toiletten im Bürobereich [...] & $12 \mathrm{~V} /$ Person $\times$ Tag & - | - Toiletten in Schulen [...] & $6 \mathrm{~V} /$ Person $\times$ Tag & - | a Bei Toiletten sollten grundsätzlich nur wassersparende Ausführungen angeschlossen werden, wie z.B. 6 l mit Zweimengen-Spülsystemen. | ANMERKUNG Sollten Waschmaschinen angeschlossen werden, würde sich der personenbezogene Tagesbedarf um 10 Liter erhöhen. — printed p.28', verification_note='md-verified 2026-09-05 (§16.3.7 Tab. 4, printed p.28 derived); "12 V" / "6 V" are the md OCR of "12 l" / "6 l"; the values are FIXED per consumer type → per the 2026-08-01 options→selection ruling P_d should be a selection (24/12/6, +10 Waschmaschine), not free-number (STAGED S-12); unit is per person and day (STAGED S-5) [VC]', verified_at=now() where id='d1c212bb-b851-45e5-a2ac-1ac9f1058fb4' and verification_status not in ('verified_against_standard','corrected');

-- A_Bew
update public.fields set verification_status='verified_against_standard', verification_quote='und aus flächenbezogenen Angaben (Grünflächen und Garten) nach $B W_{\mathrm{a}}=A_{\text {Bew. }} \times B S_{\mathrm{a}}$ | Dabei ist $B w_{a}$ Betriebswasserjahresbedarf $A_{\text {Bew. }}$. Bewässerungsflächen $B S_{a} \quad$ spezifischer Jahresbedarf — printed p.28', verification_note='md-verified 2026-09-05 (§16.3.7 Gl.(3) symbol list, printed p.28 derived) [VC]', verified_at=now() where id='cb361e1a-1cca-4eba-bf15-3d7dbe41839f' and verification_status not in ('verified_against_standard','corrected');

-- BS_a
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 4 - Ermittlung des jährlichen Betriebswasserbedarfs | - Gartenbewässerung je $1 \mathrm{~m}^{2}$ Nutzgarten Grünanlagen & - & $60 \mathrm{l} / \mathrm{m}^{2}$ | Bewässerung oder Beregnungsmengen während der Vegetationszeit von April bis September | - bei Sportanlagen & Gesamtmenge für 6 Monate & - & $200 \mathrm{l} / \mathrm{m}^{2}$ | - für Grünland bei leichtem Boden bei schwerem Boden & Gesamtmenge für 6 Monate Gesamtmenge für 6 Monate & [...] & $100 \mathrm{l} / \mathrm{m}^{2}$ bis $200 \mathrm{l} / \mathrm{m}^{2} 80 \mathrm{~V} / \mathrm{m}^{2}$ bis $150 \mathrm{~V} / \mathrm{m}^{2}$ — printed p.28', verification_note='md-verified 2026-09-05 (§16.3.7 Tab. 4, printed p.28 derived); the Grünland cell is garbled into one line by the md — reads leichter Boden 100–200 l/m², schwerer Boden 80–150 l/m² ("V" = OCR "l"); the description merges them into "80-200"; SR-2 → the ranges need a visible selection, not a free number (STAGED S-12); Sportanlagen/Grünland values are 6-month totals (April–September) [VC]', verified_at=now() where id='35a65736-d8f0-49c6-a146-836a3b40322b' and verification_status not in ('verified_against_standard','corrected');

-- BW_a
update public.fields set verification_status='verified_against_standard', verification_quote='Der jährliche Betriebswasserbedarf kann aus den Bedarfswerten nach Tabelle 4 ermittelt werden. | Der Betriebswasserbedarf im Haushalt setzt sich zusammen aus personenbezogenen Angaben (z. B. Toilette) nach $B W_{\mathrm{a}}=P_{\mathrm{d}} \times n \times 365$ [...] und aus flächenbezogenen Angaben (Grünflächen und Garten) nach $B W_{\mathrm{a}}=A_{\text {Bew. }} \times B S_{\mathrm{a}}$ | Der Betriebswasserbedarf für gewerbliche und industrielle Bereiche ist anwendungsbezogen zu ermitteln. — printed p.28', verification_note='md-verified 2026-09-05 (§16.3.7, printed p.28 derived); household demand "setzt sich zusammen aus [...] und aus [...]" = both components ADD, yet equations 2 and 3 each write BW_a on their own and no printed sum exists — composition ruling needed (STAGED S-13); for gewerbe_industrie BW_a is "anwendungsbezogen zu ermitteln" (engineer_input, not Gl.(2)/(3)) [VC]', verified_at=now() where id='4c48dac1-b0ac-41d2-baf0-cfa6372e9a00' and verification_status not in ('verified_against_standard','corrected');

-- V_n
update public.fields set verification_status='verified_against_standard', verification_quote='Der Betriebswasserbedarf muss mit dem jährlichen Regenwasserertrag verglichen werden, wobei der ermittelte kleinere Wert in die Bemessung des Nutzvolumens aufgenommen wird. Von diesem ermittelten, kleineren Wert werden $6 \%$ als ausreichendes Nutzvolumen angenommen. $V_{\mathrm{n}}=$ Minimum von $\left(B W_{\mathrm{a}}\right.$ oder $\left.E_{\mathrm{R}}\right) \times 0,06$ | Bei dieser Nutzvolumenbemessung wird der Regenwasserertrag optimal ausgenutzt bzw. bei gefülltem Speicher Betriebswasser für 3 Wochen bevorratet. — printed p.29', verification_note='md-verified 2026-09-05 (§16.3.8, printed p.29 derived); derived field — engine output of equation 4 [VC]', verified_at=now() where id='0bf17ca7-a14e-4d1e-89f4-6f5d191f75b6' and verification_status not in ('verified_against_standard','corrected');

-- mindestwasservolumen
update public.fields set verification_status='verified_against_standard', verification_quote='verfahrenstechnisch bedingtes Restwasservolumen zur Sicherstellung eines Wasserstandes bei dem zum Schutz der Pumpe weder Sediment, noch Schwimmschicht angesaugt werden | Bei der Auswahl des Speichervolumens (Nennvolumens) ist zu berücksichtigen, dass verfahrensbedingt ein Mindestwasservolumen für die Nutzung nicht zur Verfügung steht. Das vom Hersteller angegebene Nennvolumen besteht aus dem Mindestwasservolumen und dem Nutzvolumen, das Gegenstand der folgenden Bemessungsverfahren ist. — printed p.6–8, p.25', verification_note='md-verified 2026-09-05 (§3.11 + §16.1, printed p.6–8, p.25 derived); the printed identity Nennvolumen = Mindestwasservolumen + Nutzvolumen has no Nennvolumen field and no equation (STAGED S-11l); clause retag "§3.11; §16.1" proposed in STAGED S-4 [VC]', verified_at=now() where id='8ed9145b-4e43-47a7-be3b-88560b59f02c' and verification_status not in ('verified_against_standard','corrected');

-- bemessungsverfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Um die Forderungen der Praxis zu erfüllen, werden drei Bemessungsverfahren unterschieden: - ein verkürztes Verfahren für kleine Anlagen (z. B. Ein- und Zweifamilienhäuser), bei dem keine Berechnungen durchgeführt werden müssen; - ein vereinfachtes Verfahren für alle Anlagengrößen mit dem Ziel, einen Rechengang zu erhalten, der ohne großen Aufwand genügend genaue Ergebnisse für den Entwurf und die Ausführung liefert; - ein differenziertes Verfahren für alle Anlagengrößen mit dem Ziel, vor allem für große Anlagen eine bessere Annäherung an die wirklichen Betriebsverhältnisse zu erreichen. — printed p.25', verification_note='md-verified 2026-09-05 (§16.1, printed p.25 derived); enum = the three printed methods; only §16.3 is encoded — the §16.2 preconditions/rules (500–800 mm, Dachflächen, 25–50 l/m², 800–1000 l je Nutzer) and §16.4 (5–10 Jahre Simulation) have no fields/gates and gate CR-10 demands the §16.3 outputs for every method (STAGED S-7) [VC]', verified_at=now() where id='4d300cbc-f1f5-4c9b-a209-f97d90210379' and verification_status not in ('verified_against_standard','corrected');

-- ---------- DIN-1989-1-05 Versickerung des Überlaufs, Rückstauschutz und Inbetriebnahme ----------

-- ueberlauf_versickerung
update public.fields set verification_status='verified_against_standard', verification_quote='Gestatten die vorhandenen Bodenverhältnisse eine Regenwasserversickerung, sollte das aus dem Speicher überlaufende Wasser versickert werden (Schacht, Rigole, Mulde oder Mulden-Rigole). Bei Metalldächern sind die landesspezifischen Regelungen zur Versickerung zu beachten. | Bei Anschluss der Überlaufleitung an eine Muldenversickerung ist eine Kleintiersperre (Siphon, Rattenschutz, Froschklappe) vorzusehen. — printed p.20', verification_note='md-verified 2026-09-05 (§13, printed p.20 derived); "sollte" — recommendation, correctly not required [VC]', verified_at=now() where id='a3316fa0-e618-43ab-9a6a-228074ef62b0' and verification_status not in ('verified_against_standard','corrected');

-- versickerung_bemessung_a138
update public.fields set verification_status='verified_against_standard', verification_quote='Baugrundsätze und Bemessung von Regenwasserversickerungsanlagen sind im ATV-Arbeitsblatt A 138 festgelegt. Bei der Bemessung von Versickerungsanlagen kann ggf. die Rückhaltewirkung von Regenwasserspeichern berücksichtigt werden. | Bei Einsatz eines Filters mit separater Ableitung von Fremdstoffen darf ein Anschluss dieser Leitung an unterirdische Versickerungssysteme nur mit einer Vorreinigung des Wassers vorgenommen werden, um ein Zusetzen der Versickerungsanlagen zu vermeiden. — printed p.20', verification_note='md-verified 2026-09-05 (§13, printed p.20 derived); cross-reference to ATV-A 138 (today DWA-A 138, encoded separately) [VC]', verified_at=now() where id='b4a11407-30a4-4b70-88bf-33bf7576d46e' and verification_status not in ('verified_against_standard','corrected');

-- whg_erlaubnis
update public.fields set verification_status='verified_against_standard', verification_quote='Das unmittelbare Einleiten von gesammeltem Niederschlagswasser (Versickerung) in ein Gewässer (Grundwasser) stellt eine Gewässerbenutzung dar. Für das Versickern von Niederschlagswasser ist nach § 7 Wasserhaushaltsgesetz (WHG) grundsätzlich eine Erlaubnis bei der zuständigen Wasserbehörde zu beantragen. Die Regelungen der Bundesländer für die Versickerung von Niederschlagswasser und ggf. vorhandene Regelungen zur erlaubnisfreien Versickerung sind zu beachten. — printed p.20', verification_note='md-verified 2026-09-05 (§13, printed p.20 derived); "grundsätzlich" with erlaubnisfrei exceptions — no gate ties it to ueberlauf_versickerung today (STAGED S-11c, warn); the WHG § numbering is the 2002 text [VC]', verified_at=now() where id='32be0b5b-df70-453a-babf-edccbaffb25d' and verification_status not in ('verified_against_standard','corrected');

-- rueckstauschutz_art
update public.fields set verification_status='verified_against_standard', verification_quote='Falls der Überlauf von Regenwasserspeichern der Mischwasserkanalisation oder von in Kellerräumen aufgestellten Regenwasserspeichern der Regenwasserkanalisation zugeführt wird, ist dieser rückstaufrei (siehe Bild 2) oder über eine Hebeanlage (siehe Bild 3) auszuführen. [...] Sie muss DIN EN 12050-2 entsprechen und ist nach DIN EN 12056-4 und DIN 1986-100 zu bemessen. | Der Überlauf eines Erdspeichers kann durch einen Rückstauverschluss für fäkalienfreies Abwasser nach DIN 1997-1 an einen Regenwasserwasserkanal angeschlossen werden (siehe Bild 4). [...] Ein Anschluss an einen Mischwasserkanal über einen Rückstauverschluss ist nicht zulässig. | Falls keine weiteren Flächen direkt in die Versickerungsanlage entwässert werden und diese nicht an die Kanalisation angeschlossen ist, kann auf eine Rückstausicherung für die Überlaufleitung des Regenwasserspeichers verzichtet werden. — printed p.20', verification_note='md-verified 2026-09-05 (§14 + §13, printed p.20 derived); the four tokens map to the three printed devices + the §13 waiver; the printed admissibility rules depend on the overflow destination (Mischwasserkanal / Regenwasserkanal / Versickerung) and on Keller vs Erdspeicher — no destination field exists and gate CR-12 accepts every token (STAGED S-8) [VC]', verified_at=now() where id='e579ba67-1b50-41f9-b4a6-69a59beeed7e' and verification_status not in ('verified_against_standard','corrected');

-- rueckstauebene_bekannt
update public.fields set verification_status='verified_against_standard', verification_quote='Angeschlossene Grundstücksentwässerungsanlagen, deren Überlauf unter der Rückstauebene liegt, sind daher wirkungsvoll und dauerhaft gegen schädliche Folgen von Rückstau durch eine sachgemäße Installation und einen bestimmungsgemäßen Betrieb zu sichern. Die maßgebende Rückstauebene wird von den Betreibern der öffentlichen Abwasseranlagen in den Entwässerungssatzungen festgelegt. Ist keine Rückstauebene in den Satzungen festgelegt, gilt die Straßenoberkante als Rückstauebene. — printed p.20', verification_note='md-verified 2026-09-05 (§14, printed p.20 derived) [VC]', verified_at=now() where id='9efdcef3-d8d7-4a91-9a66-28f2efa8b5af' and verification_status not in ('verified_against_standard','corrected');

-- inbetriebnahme_fachkundig
update public.fields set verification_status='verified_against_standard', verification_quote='Die Inbetriebnahme ist durch einen Fachkundigen durchzuführen. Zur Inbetriebnahme ist ein Probelauf mit Wasser mit mehreren Schaltspielen (z. B. der Betriebswasserpumpe und der Nachspeiseeinrichtung) erforderlich. — printed p.30', verification_note='md-verified 2026-09-05 (§17.2, printed p.30 derived) [VC]', verified_at=now() where id='f758a5de-e4c6-4249-9ada-b3d40a4ed582' and verification_status not in ('verified_against_standard','corrected');

-- probelauf_durchgefuehrt
update public.fields set verification_status='verified_against_standard', verification_quote='Vor, während bzw. nach diesem Probelauf sind z. B. zu prüfen: - Zustand des Filtersystems - Dichtheit der Zu-/Überlaufleitungen - ggf. Funktion der Rückstausicherung - Dichtheit der Regenwasserspeicher und deren Anschlüsse - Dichtheit der Betriebswasserleitung - Funktion der Betriebswasserpumpe - Einstellung der Schalthöhen im Speicher - Pumpen- und Strömungsgeräusche - Nachspeisung (bei Trinkwasseranschluss - Freier Auslauf) - Speicherinhaltsanzeige - Wasserzähler - elektrische Absicherung der Anlage nach VDE-Vorschriften - ordnungsgemäße Kennzeichnung — printed p.30', verification_note='md-verified 2026-09-05 (§17.2, printed p.30 derived); the checklist is exemplary ("z. B.") but the Probelauf itself is "erforderlich" [VC]', verified_at=now() where id='562b445e-e253-4408-b354-e93bbc401ee7' and verification_status not in ('verified_against_standard','corrected');

-- inbetriebnahmeprotokoll
update public.fields set verification_status='verified_against_standard', verification_quote='Über die durchgeführte Inbetriebnahme und die Übergabe der Unterlagen ist zweckmäßigerweise ein Inbetriebnahme- und Einweisungsprotokoll anzufertigen (siehe Anhang B). | Beispiel eines Inbetriebnahme- und Einweisungsprotokolls für eine Regenwassernutzungsanlage | Die Einweisung für den Betrieb der Anlage ist erfolgt; die erforderlichen Betriebsunterlagen und vorhandenen Bedienungs- und Wartungsanleitungen gemäß Aufstellung wurden vollständig ausgehändigt. — printed p.30, p.35', verification_note='md-verified 2026-09-05 (§17.2 + Anhang B (informativ), printed p.30, p.35 derived); "zweckmäßigerweise" = advisory, Anhang B is informative — block gate CR-13 and is_required=true over-enforce this half (STAGED S-9/S-10) [VC]', verified_at=now() where id='07c91b3d-c63e-485b-bf24-30750d024b4b' and verification_status not in ('verified_against_standard','corrected');

-- betriebsanleitung_uebergeben
update public.fields set verification_status='verified_against_standard', verification_quote='Für den Betrieb einer Regenwassernutzungsanlage ist dem Betreiber eine Betriebs-, Wartungs- und Bedienungsanleitung zu übergeben. | In DIN 18381 wird differenziert, welche Unterlagen über Betrieb, Bedienung der Systeme dem Auftraggeber bei der Übergabe unaufgefordert zu übergeben sind. | Die Betriebsanleitung muss folgende Hinweise für den Betreiber der Anlage enthalten: - Hinweis auf diese Norm — printed p.29, p.30', verification_note='md-verified 2026-09-05 (§17.1 + §17.3, printed p.29, p.30 derived); the hand-over obligation sits in §17.1 (field tagged §17.3 only — retag in STAGED S-4); hard obligation with NO gate (STAGED S-11b) [VC]', verified_at=now() where id='1acd4b0b-544a-4f74-a353-f8b15cfc9664' and verification_status not in ('verified_against_standard','corrected');

-- ---------- DIN-1989-1-06 Betrieb, Inspektion und Wartung ----------

-- inspektion_intervall
update public.fields set verification_status='verified_against_standard', verification_quote='Inspektions- und Wartungsarbeiten an Regenwassernutzungsanlagen müssen durch den Betreiber oder einen Fachkundigen in Zeitintervallen nach Tabelle 5 durchgeführt werden [...] | Tabelle 5 - Inspektions- und Wartungsmaßnahmen | Anlagenteil/Apparat & Maßnahme & Durchführung & Zeitspanne | Dachabläufe & Inspektion & Prüfung auf ungehinderten Ablauf (auch etwaiger Überläufe), Dichtheit, Schmutzfänge reinigen, ggf. Beheizung prüfen & 6 Monate | Filtersysteme & Inspektion & Kontrolle des Zustandes des Filters & 1 Jahr [...] | Rückstauverschlüsse & Inspektion & Betriebsverschluss ggf. Notverschluss betätigen & 1 Monat | Längere oder kürzere Zeitintervalle können sich durch spezielle anlagen- und betriebstechnische Randbedingungen ergeben. — printed p.31–33', verification_note='md-verified 2026-09-05 (§18 Tab. 5, printed p.31–33 derived); the three tokens are Tab. 5 inspection spans (Tab. 5 also prints 3 Monate, 6 Jahre, ≈10 Jahre for Wartung); "shortest interval" is an EKOWAI roll-up the standard does not define per se — is_required review in STAGED S-10 [VC]', verified_at=now() where id='25eaaacb-85ea-4dfe-b202-069e0ac4196d' and verification_status not in ('verified_against_standard','corrected');

-- wartung_fachkundig
update public.fields set verification_status='verified_against_standard', verification_quote='Inspektions- und Wartungsarbeiten an Regenwassernutzungsanlagen müssen durch den Betreiber oder einen Fachkundigen in Zeitintervallen nach Tabelle 5 durchgeführt werden und für die in Tabelle 5 aufgeführten Anlagenteile in folgendem Umfang inspiziert bzw. gewartet werden. | - Inspektionen dürfen vom Betreiber der Anlage selbst vorgenommen werden. - Wartungen und Instandsetzungen sind von Fachkundigen durchzuführen. — printed p.31, p.33', verification_note='md-verified 2026-09-05 (§18, printed p.31, p.33 derived) [VC]', verified_at=now() where id='44944ccf-7fd9-4439-965a-9df95970f206' and verification_status not in ('verified_against_standard','corrected');

-- filter_reinigung_jaehrlich
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 5 - Inspektions- und Wartungsmaßnahmen | Anlagenteil/Apparat & Maßnahme & Durchführung & Zeitspanne | Filtersysteme & Inspektion & Kontrolle des Zustandes des Filters & 1 Jahr [...] | & Wartung & Reinigung des Filters & 1 Jahr | a nach Standortbedingungen und Herstellerangaben — printed p.31, p.33', verification_note='md-verified 2026-09-05 (§18 Tab. 5 Filtersysteme rows, printed p.31, p.33 derived); footnote a (site conditions / manufacturer) qualifies the inspection span [VC]', verified_at=now() where id='7d358cba-854e-42b4-954c-b55cd3b909eb' and verification_status not in ('verified_against_standard','corrected');

-- speicher_reinigung_jahre
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 5 - Inspektions- und Wartungsmaßnahmen | Regenwasserspeicher einschließlich Einbauteile & Inspektion & Prüfung der Sauberkeit, Dichtheit, Standsicherheit & 1 Jahr | & Wartung & Entleerung, Reinigung der Speicherinnenflächen, ggf. Entnahme des Sedimentes & $\approx 10$ Jahre | Längere oder kürzere Zeitintervalle können sich durch spezielle anlagen- und betriebstechnische Randbedingungen ergeben. — printed p.31, p.33', verification_note='md-verified 2026-09-05 (§18 Tab. 5 Regenwasserspeicher rows, printed p.31, p.33 derived); "≈ 10 Jahre" is approximate and explicitly adjustable — engineer value, no hard limit [VC]', verified_at=now() where id='ea8c8069-636f-400e-9c87-10b6ad5af741' and verification_status not in ('verified_against_standard','corrected');

-- wasserzaehler_austausch_jahre
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 5 - Inspektions- und Wartungsmaßnahmen | Wasserzähler & Inspektion & Prüfung von Wasserzählern auf Funktion und Dichtheit & 1 Jahr | & Wartung & Wasserzähler sind nach den eichrechtlichen Vorschriften alle 6 Jahre im Austausch zu erneuern, wenn sie im geschäftlichen Verkehr verwendet werden & 6 Jahre — printed p.31–32', verification_note='md-verified 2026-09-05 (§18 Tab. 5 Wasserzähler rows, printed p.31–32 derived); 6 Jahre is a printed fixed value (Eichrecht) held in a hand-enterable number field — standard_fixed-editable finding, warn gate ≤ 6 proposed in STAGED S-11h [VC]', verified_at=now() where id='3678fde9-734b-4ddc-841e-26f3225652ca' and verification_status not in ('verified_against_standard','corrected');

-- betriebsbuch_gefuehrt
update public.fields set verification_status='verified_against_standard', verification_quote='- Zur besseren Kontrolle und Überprüfung der Funktion der Regenwassernutzungsanlage sollte ein Betriebsbuch mit der monatlichen Wasserentnahme und ggf. Wassernachspeisung geführt werden. | - Durch regelmäßiges Ablesen der evtl. installierten Wasserzähler können Wasserverluste erkannt werden ( $z$. B. Leckagen im Speicher und verstopfte Filter). — printed p.30', verification_note='md-verified 2026-09-05 (§17.3, printed p.30 derived); "sollte" — recommendation, correctly not required [VC]', verified_at=now() where id='2e98eeca-3e18-448f-871a-01d223ed0b6a' and verification_status not in ('verified_against_standard','corrected');

-- ######################## SECTION B — equation quote backfill, STATUS UNCHANGED ########################
-- All 4 equations are already verified_against_standard (encode-time, source_quote stored) but verification_quote is
-- NULL. Only verification_quote is filled and a " | md-quote 2026-09-05 (…) [VC]" tag appended to verification_note;
-- the guard "verification_quote is null" makes every statement idempotent. Rollback: null the quote where the note
-- carries the tag.

-- Gl.(1) E_R = A_A * e * h_N * eta
update public.equations set verification_quote='Die jährliche theoretisch speicherbare Regenwassermenge ist nach Gleichung (1) zu berechnen: | E_{\mathrm{R}}=A_{\mathrm{A}} \times e \times h_{\mathrm{N}} \times \eta \tag{1} | Dabei ist $E_{\mathrm{R}} \quad$ der Regenwasserertrag in Liter je Jahr (I/a) $A_{\mathrm{A}} \quad$ die Auffangfläche in Quadratmeter ( $\mathrm{m}^{2}$ ) e der Ertragsbeiwert in \% $h_{\mathrm{N}} \quad$ die Niederschlagshöhe in Liter je Quadratmeter $\left(\mathrm{l} / \mathrm{m}^{2}\right)$ oder Millimeter $(\mathrm{mm})$ $\eta \quad$ der hydraulische Filterwirkungsgrad. — printed p.27', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§16.3.6 Gl.(1), printed p.27 derived; formula matches the encoded E_R = A_A * e * h_N * eta; status unchanged — quote backfill only) [VC]' where id='5c32f168-f50b-492b-bde8-bec4a909d676' and verification_quote is null;

-- Gl.(2) BW_a = P_d * n * 365
update public.equations set verification_quote='Der Betriebswasserbedarf im Haushalt setzt sich zusammen aus personenbezogenen Angaben (z. B. Toilette) nach $B W_{\mathrm{a}}=P_{\mathrm{d}} \times n \times 365$ | Dabei ist $B W_{\mathrm{a}} \quad$ Betriebswasserjahresbedarf $P_{\mathrm{d}} \quad$ personenbezogener Tagesbedarf n Anzahl der Personen — printed p.28', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§16.3.7, printed p.28 derived; the md prints no equation number — "(2)" is the encoding label; formula matches; status unchanged — quote backfill only) [VC]' where id='8f516224-e4a7-46bf-a44e-6d571484f90a' and verification_quote is null;

-- Gl.(3) BW_a = A_Bew * BS_a
update public.equations set verification_quote='und aus flächenbezogenen Angaben (Grünflächen und Garten) nach $B W_{\mathrm{a}}=A_{\text {Bew. }} \times B S_{\mathrm{a}}$ | Dabei ist $B w_{a}$ Betriebswasserjahresbedarf $A_{\text {Bew. }}$. Bewässerungsflächen $B S_{a} \quad$ spezifischer Jahresbedarf — printed p.28', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§16.3.7, printed p.28 derived; the md prints no equation number — "(3)" is the encoding label; formula matches; the standard composes household BW_a from Gl.(2) AND Gl.(3) ("setzt sich zusammen aus … und aus …") — see STAGED S-13; status unchanged — quote backfill only) [VC]' where id='4d57786c-99cd-400f-843e-93bb2d16166f' and verification_quote is null;

-- Gl.(4) V_n = min(BW_a, E_R) * 0.06
update public.equations set verification_quote='Der Betriebswasserbedarf muss mit dem jährlichen Regenwasserertrag verglichen werden, wobei der ermittelte kleinere Wert in die Bemessung des Nutzvolumens aufgenommen wird. Von diesem ermittelten, kleineren Wert werden $6 \%$ als ausreichendes Nutzvolumen angenommen. $V_{\mathrm{n}}=$ Minimum von $\left(B W_{\mathrm{a}}\right.$ oder $\left.E_{\mathrm{R}}\right) \times 0,06$ | Bei dieser Nutzvolumenbemessung wird der Regenwasserertrag optimal ausgenutzt bzw. bei gefülltem Speicher Betriebswasser für 3 Wochen bevorratet. — printed p.29', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§16.3.8, printed p.29 derived; the md prints no equation number — "(4)" is the encoding label; formula matches min(BW_a, E_R) × 0,06; status unchanged — quote backfill only) [VC]' where id='9f2b0686-05c4-46ac-90bc-73a7ad19dfe8' and verification_quote is null;
